window.BANCO = window.BANCO || [];
window.BANCO.push({"id":"windows","nombre":"Windows 11","bloques":[{"id":"windows-general","nombre":"Windows 11"}],"calendarios":{},"casos":[{"id":"test-win-in-01","titulo":"INAP 2019 ord.","texto":"","corto":true,"ids":["win-in-01-044","win-in-01-045","win-in-01-046","win-in-01-047","win-in-01-049","win-in-01-050","win-in-01-051"]},{"id":"test-win-in-02","titulo":"INAP 2019 extra","texto":"","corto":true,"ids":["win-in-02-044","win-in-02-046","win-in-02-047","win-in-02-048","win-in-02-049","win-in-02-050","win-in-02-051"]},{"id":"test-win-in-03","titulo":"INAP 2022 ord.","texto":"","corto":true,"ids":["win-in-03-045","win-in-03-046","win-in-03-047","win-in-03-048","win-in-03-050"]},{"id":"test-win-in-04","titulo":"INAP 2022 extra","texto":"","corto":true,"ids":["win-in-04-045","win-in-04-046","win-in-04-047","win-in-04-048","win-in-04-049","win-in-04-051"]},{"id":"test-win-in-05","titulo":"INAP 14 dic. 2024","texto":"","corto":true,"ids":["win-in-05-045","win-in-05-046","win-in-05-047","win-in-05-049","win-in-05-050","win-in-05-051","win-in-05-066"]},{"id":"test-win-in-06","titulo":"INAP 2024 extra","texto":"","corto":true,"ids":["win-in-06-048","win-in-06-049","win-in-06-050","win-in-06-051","win-in-06-052","win-in-06-054","win-in-06-055","win-in-06-056","win-in-06-057","win-in-06-058","win-in-06-070"]},{"id":"test-win-in-07","titulo":"INAP 23 mayo 2026","texto":"","corto":true,"ids":["win-in-07-045","win-in-07-047","win-in-07-048","win-in-07-049","win-in-07-050","win-in-07-067"]},{"id":"test-win-in-08","titulo":"INAP julio 2026 extra","texto":"","corto":true,"ids":["win-in-08-044","win-in-08-046","win-in-08-047","win-in-08-048","win-in-08-050"]}],"preguntas":[{"id":"win-in-01-044","origen":"oficiales","test":"INAP 2019 ord.","n":44,"enunciado":"Para ver las especificaciones de Windows 11 y del equipo, ¿cuál de las siguientes es la secuencia correcta?","opciones":["Configuración > Cuentas > Tu información","Configuración > Bluetooth y dispositivos","Configuración > Personalización > Estado","Configuración > Sistema > Información"],"correcta":3,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2019 ord. · nº 44","justificaciones":["","","","Es esta. La ruta es **Configuración > Sistema > Información** (antes «Acerca de»). Esa página muestra el procesador, la RAM, el tipo de sistema y la edición y versión de Windows 11, y tiene el botón Copiar para pegar los datos."],"ojo":"**Cuentas > Tu información** solo guarda los datos del usuario, y **Bluetooth y dispositivos** es para periféricos. En Personalización no hay ninguna página de estado. Oficial reescrita para Windows 11: la original se refería a algo que cambió en esa versión."},{"id":"win-in-01-045","origen":"oficiales","test":"INAP 2019 ord.","n":45,"enunciado":"En la ventana Configuración de Windows 11, ¿en qué apartado puedo configurar las 'Opciones de inicio de sesión'?","opciones":["Aplicaciones.","Red e Internet.","Cuentas.","Sistema."],"correcta":2,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2019 ord. · nº 45","justificaciones":["","","Es esta. Las opciones de inicio de sesión (**Windows Hello** con cara o huella, PIN, clave de seguridad y contraseña) están en **Configuración > Cuentas > Opciones de inicio de sesión**, porque tienen que ver con la identidad del usuario.",""],"ojo":"Para ubicar un ajuste, piensa a qué se refiere: hardware y pantalla son Sistema, wifi y VPN son Red e Internet, y todo lo que identifica a la persona está en Cuentas. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-01-046","origen":"oficiales","test":"INAP 2019 ord.","n":46,"enunciado":"En el Explorador de archivos de Windows 11, en el menú Ver, contamos con distintos diseños. ¿Cuál de los siguientes ofrece más información de los archivos en pantalla?","opciones":["Iconos medianos.","Lista.","Iconos pequeños.","Detalles."],"correcta":3,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2019 ord. · nº 46","justificaciones":["","","","Es esta. El diseño **Detalles** muestra una fila por archivo con varias columnas: nombre, fecha de modificación, tipo y tamaño. Es el que más información da. Se elige en el menú **Ver > Mostrar** o en el botón **Ver** del Explorador de archivos."],"ojo":"Los diseños de **iconos** y la **lista** solo enseñan el nombre y, a lo sumo, la miniatura. En Detalles, además, se puede añadir más columnas con clic derecho en la cabecera. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-01-047","origen":"oficiales","test":"INAP 2019 ord.","n":47,"enunciado":"Estamos utilizando dos pantallas conectadas a un ordenador con Windows 11. En la configuración de Pantalla, en la opción \"Varias pantallas\" seleccionamos \"Duplicar estas pantallas\". ¿Qué opción describe lo que podemos ver?","opciones":["Vemos objetos diferentes en cada pantalla y podemos mover elementos entre las dos pantallas.","Vemos lo mismo en las dos pantallas.","Vemos todo el contenido en la primera pantalla. La segunda pantalla se queda en negro.","Se crea una copia duplicada en el disco duro de los archivos que movemos a la segunda pantalla."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2019 ord. · nº 47","justificaciones":["","Es esta. **Duplicar estas pantallas** envía la misma imagen a las dos pantallas, lo que resulta útil para proyectar. Se elige en **Configuración > Sistema > Pantalla > Varias pantallas**.","",""],"ojo":"Las otras opciones del mismo menú son **Extender estas pantallas** (escritorio continuo, se mueven ventanas de una a otra) y **Mostrar solo en 1** o **solo en 2**. Ninguna copia archivos en el disco. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-01-049","origen":"oficiales","test":"INAP 2019 ord.","n":49,"enunciado":"Con respecto al \"Acceso rápido\" en el Explorador de archivos de Windows 11, señale la opción correcta:","opciones":["Podemos seleccionar una carpeta y anclarla al Acceso rápido.","Sólo aparecen en el Acceso rápido las carpetas más utilizadas.","Sólo se pueden anclar al Acceso rápido archivos, no carpetas.","Para anclar una carpeta al Acceso rápido es preciso que esté en la biblioteca Documentos."],"correcta":0,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2019 ord. · nº 49","justificaciones":["Es esta. Cualquier **carpeta** se puede **anclar al Acceso rápido** con clic derecho > **Anclar a Acceso rápido**, esté donde esté. Además de lo anclado a mano, el Explorador añade solo las carpetas usadas con frecuencia.","","",""],"ojo":"Se anclan **carpetas**, no archivos sueltos, y no hace falta que estén en una biblioteca. Que aparezcan «solo las más usadas» es falso, porque las ancladas se quedan fijas. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-01-050","origen":"oficiales","test":"INAP 2019 ord.","n":50,"enunciado":"¿Cuál de las siguientes NO es una herramienta de accesibilidad de Windows 11?","opciones":["Lupa.","Mapa de caracteres.","Narrador.","Reconocimiento de voz de Windows."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2019 ord. · nº 50","justificaciones":["","Es esta. El **Mapa de caracteres** sirve para copiar símbolos y caracteres especiales de una fuente, no es una herramienta de accesibilidad. Las otras tres sí lo son: la **Lupa** amplía la pantalla, el **Narrador** lee en voz alta lo que hay y el **Reconocimiento de voz** permite controlar el equipo hablando.","",""],"ojo":"En preguntas «cuál NO es», identifica primero las tres que sí lo son, y la que sobra es la respuesta. Las herramientas de accesibilidad están en **Configuración > Accesibilidad**. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-01-051","origen":"oficiales","test":"INAP 2019 ord.","n":51,"enunciado":"Señale la respuesta INCORRECTA si queremos visualizar la versión de Windows que estamos utilizando:","opciones":["En el Explorador de archivos, clic derecho en Este equipo, y en el menú contextual, clic en Propiedades.","Clic en el menú Inicio > Configuración > Sistema > Acerca de.","Abrir el Centro de actividades y hacer clic en Administrar notificaciones.","En la barra de búsqueda del menú Inicio escribir \"winver\" (sin comillas) y presionar la tecla Intro."],"correcta":2,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2019 ord. · nº 51","justificaciones":["","","Es esta. El **Centro de actividades** (hoy Centro de notificaciones) con **Administrar notificaciones** gestiona los avisos y no dice nada de la versión de Windows. Por eso es la falsa y la que hay que marcar.",""],"ojo":"Las tres ciertas son: **winver** en la búsqueda, clic derecho en **Este equipo > Propiedades** y **Configuración > Sistema > Acerca de**. La pregunta pide la INCORRECTA, así que la que no funciona es la buena."},{"id":"win-in-02-044","origen":"oficiales","test":"INAP 2019 extra","n":44,"enunciado":"¿Qué es un acceso directo en Windows 11?","opciones":["Es un perfil de permisos para acceder a Windows 11, similar al del Administrador.","Es un fichero simbólico que podemos crear y que permite acceder a un determinado programa o archivo.","Es una opción de acceso a la cuenta de otro usuario, que nos permite cambiar su contraseña sin ser Administrador.","Es una sección del Explorador de archivos en la que encontramos los últimos archivos eliminados."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2019 extra · nº 44","justificaciones":["","Es esta. Un **acceso directo** es un archivo pequeño (extensión .lnk) que **apunta a un programa, archivo o carpeta** y permite abrirlo desde otro sitio sin moverlo. Se crea con clic derecho > **Mostrar más opciones > Crear acceso directo**, o arrastrando con Alt.","",""],"ojo":"Borrar el acceso directo no borra el archivo original. No es un permiso ni una cuenta, ni una sección de eliminados (eso es la Papelera). Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-02-046","origen":"oficiales","test":"INAP 2019 extra","n":46,"enunciado":"En Windows 11, ¿para qué sirve «No molestar»?","opciones":["Silencia los avisos de notificación, que siguen llegando al Centro de notificaciones.","Es una guía incluida en Windows con una serie de consejos para la concentración.","Gradúa automáticamente el brillo y el contraste de la pantalla.","Cierra las aplicaciones en segundo plano para liberar memoria."],"correcta":0,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2019 extra · nº 46","justificaciones":["Es esta. **No molestar** oculta los avisos emergentes y sonoros, pero las notificaciones **siguen llegando** y se guardan en el Centro de notificaciones. Se activa desde la campana de notificaciones o en Configuración > Sistema > Notificaciones.","","",""],"ojo":"No cierra aplicaciones ni cambia el brillo. Es distinto de **Concentración**, que además inicia un temporizador y silencia los avisos de la barra de tareas. En Windows 10 se llamaba Asistente de concentración. Oficial reescrita para Windows 11: la original se refería a algo que cambió en esa versión."},{"id":"win-in-02-047","origen":"oficiales","test":"INAP 2019 extra","n":47,"enunciado":"Indique la herramienta de Windows a la que corresponde la siguiente descripción \"editor de texto incluido en el sistema operativo de funcionalidades muy simples\":","opciones":["Herramienta Recortes.","Bloc de notas.","Windows Media Player.","Escritorio remoto."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2019 extra · nº 47","justificaciones":["","Es esta. El **Bloc de notas** es el editor de **texto sin formato** (.txt) más sencillo que viene con Windows: no tiene negritas ni tipos de letra distintos.","",""],"ojo":"La **herramienta Recortes** captura la pantalla, **Windows Media Player** reproduce multimedia y **Escritorio remoto** conecta con otro equipo."},{"id":"win-in-02-048","origen":"oficiales","test":"INAP 2019 extra","n":48,"enunciado":"Con la combinación por defecto de las teclas Windows + E, ¿qué herramienta de Windows se abre?","opciones":["Configuración.","Explorador de archivos.","Administrador de tareas.","Centro de movilidad."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2019 extra · nº 48","justificaciones":["","Es esta. **Windows + E** abre el **Explorador de archivos**. La E es de «Explorador».","",""],"ojo":"Otros atajos muy preguntados: **Windows + I** abre Configuración, **Windows + D** muestra el escritorio, **Windows + L** bloquea el equipo y **Ctrl + Mayús + Esc** abre el Administrador de tareas."},{"id":"win-in-02-049","origen":"oficiales","test":"INAP 2019 extra","n":49,"enunciado":"¿Cuál de las siguientes formas de abrir el Explorador de archivos de Windows NO es válida?","opciones":["Clic con el botón derecho del ratón en Inicio > Explorador de archivos.","Clic izquierdo de ratón en Inicio y escribir Explorador de archivos.","Combinación de teclas Windows + E.","Ir a Inicio > Configuración de Windows > Sistema > Explorador de archivos."],"correcta":3,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2019 extra · nº 49","justificaciones":["","","","Es esta. No existe ninguna ruta **Configuración > Sistema > Explorador de archivos**. Las otras tres formas sí abren el Explorador: clic derecho en Inicio, buscar «Explorador de archivos» en Inicio y **Windows + E**."],"ojo":"En preguntas «NO es válida», fíjate en las rutas inventadas: el Explorador es un programa, no un apartado de la Configuración."},{"id":"win-in-02-050","origen":"oficiales","test":"INAP 2019 extra","n":50,"enunciado":"Si Windows 11 está en español, ¿cuál es el método abreviado de teclado del Explorador de archivos para seleccionar la barra de direcciones?","opciones":["Ctrl + B.","Alt + D.","Ctrl + W.","Alt + P."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2019 extra · nº 50","justificaciones":["","Es esta. **Alt + D** selecciona la **barra de direcciones** del Explorador de archivos y permite escribir una ruta. También funcionan Ctrl + L y F4.","",""],"ojo":"Con otras teclas se hace otra cosa: **Alt + P** muestra u oculta el panel de vista previa, **Ctrl + W** cierra la ventana y **Ctrl + E** o F3 van al cuadro de búsqueda. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-02-051","origen":"oficiales","test":"INAP 2019 extra","n":51,"enunciado":"¿Cuál de las siguientes opciones es verdadera con respecto al funcionamiento del bloc de notas de Windows 11?","opciones":["No se pueden configurar ni encabezados ni pies de página.","Es posible configurar la alineación de los encabezados y pies de página, así como incluir la fecha actual, la hora actual, el nombre del documento y el número de página.","Es posible incluir un texto de encabezado y otro de pie de página, pero no es posible ningún tipo de configuración del formato para estos textos.","Es posible configurar los encabezados y pies de página, pero sólo es posible añadir los campos de fecha y hora actual, y no la alineación del texto ni el nombre del documento o el número de página."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2019 extra · nº 51","justificaciones":["","Es esta. En el **Bloc de notas**, **Archivo > Configurar página** permite un encabezado y un pie de página. Mediante códigos como **&f** (nombre del archivo), **&d** (fecha), **&t** (hora) o **&p** (número de página) se incluyen esos datos, y con **&l**, **&c** y **&r** se alinea a la izquierda, centro o derecha.","",""],"ojo":"Aunque es un editor simple, el Bloc de notas sí permite encabezados y pies, pero no formato de texto (negrita, color o tipo de letra por fragmento). Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-03-045","origen":"oficiales","test":"INAP 2022 ord.","n":45,"enunciado":"¿Qué es Windows Hello?","opciones":["Es la plataforma o sistema biométrico de Windows 11.","Es un protocolo de comunicación que utiliza Windows 11.","Es la interfaz de usuario de Windows 11.","Ninguna de las anteriores."],"correcta":0,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2022 ord. · nº 45","justificaciones":["Es esta. **Windows Hello** es el sistema de **autenticación biométrica** de Windows: permite iniciar sesión sin escribir la contraseña, con reconocimiento facial, huella dactilar o PIN. Se configura en **Configuración > Cuentas > Opciones de inicio de sesión**.","","",""],"ojo":"No es un protocolo de comunicación ni la interfaz de Windows. Que ponga «Hello» en el nombre es la trampa para pensar que es un saludo o un asistente. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-03-046","origen":"oficiales","test":"INAP 2022 ord.","n":46,"enunciado":"¿Qué es el Modo Dios de Windows 11?","opciones":["No existe en Windows 11.","Es un menú oculto del sistema con gran cantidad de opciones y herramientas que no están activadas por defecto.","Es un modo para acceder a la BIOS del ordenador.","Es un modo diseñado para ofrecer seguridad y rendimiento y se ejecuta exclusivamente en aplicaciones de Microsoft Store."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2022 ord. · nº 46","justificaciones":["","Es esta. El **Modo Dios** (God Mode) es una **carpeta especial** que reúne en una sola ventana casi todas las opciones de configuración y administración del sistema. Se crea haciendo una carpeta nueva y llamándola **GodMode.{ED7BA470-8E54-465E-825C-99712043E01C}**.","",""],"ojo":"Existe en Windows 11 y no tiene que ver con la BIOS ni con ejecutar solo aplicaciones de la Microsoft Store (eso se parece al Modo S). Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-03-047","origen":"oficiales","test":"INAP 2022 ord.","n":47,"enunciado":"¿Qué ocurre en Windows 11 si pulsamos la combinación de teclas Windows + D?","opciones":["Nada.","Se muestra y oculta el escritorio.","Se cierran las ventanas activas.","Se abre el menú de botones de acceso."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2022 ord. · nº 47","justificaciones":["","Es esta. **Windows + D** minimiza todas las ventanas para mostrar el **escritorio**, y al pulsarla otra vez las restaura. No cierra nada.","",""],"ojo":"Para cerrar la ventana activa se usa **Alt + F4**. **Windows + M** minimiza todas pero no las restaura con la misma tecla. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-03-048","origen":"oficiales","test":"INAP 2022 ord.","n":48,"enunciado":"¿Cuál de las siguientes herramientas NO se encuentra en la carpeta «Herramientas de Windows» sin instalar utilidades adicionales?","opciones":["Servicios.","Monitor de recursos.","Administrador de teclado.","Visor de eventos."],"correcta":2,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2022 ord. · nº 48","justificaciones":["","","Es esta. El **Administrador de teclado** no forma parte de Windows: viene con **PowerToys**, un conjunto de utilidades de Microsoft que hay que instalar aparte. En la carpeta **Herramientas de Windows** sí vienen de serie Servicios, Monitor de recursos y Visor de eventos.",""],"ojo":"La carpeta Herramientas de Windows se abre desde Inicio > Todas las aplicaciones. Ahí están también el Administrador de tareas, Monitor de rendimiento y Programador de tareas. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-03-050","origen":"oficiales","test":"INAP 2022 ord.","n":50,"enunciado":"Cuando se recupera un archivo de la papelera de reciclaje:","opciones":["Se restaura en su anterior localización.","Se restaura en el escritorio.","Se restaura en el menú de inicio.","No es posible recuperar los ficheros de la papelera."],"correcta":0,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2022 ord. · nº 50","justificaciones":["Es esta. Al **restaurar** un archivo desde la **Papelera de reciclaje**, Windows lo devuelve a su **ubicación original**, y si la carpeta ya no existe, la vuelve a crear.","","",""],"ojo":"Solo se recupera lo que pasó por la papelera. Lo borrado con **Mayús + Supr** o desde un USB o unidad de red no se puede restaurar desde ahí."},{"id":"win-in-04-045","origen":"oficiales","test":"INAP 2022 extra","n":45,"enunciado":"En Windows 11, cuando utilizamos escritorios virtuales veremos, por defecto, en la barra de tareas que solo nos aparecerán los iconos de las ventanas abiertas del escritorio virtual que estemos usando en ese momento. ¿Se puede cambiar este comportamiento?","opciones":["No es una opción configurable.","Sí, en configuración de Multitarea, \"Escritorio virtuales\" donde dice \"En la barra de tareas, mostrar las ventanas que están abiertas en\", cambiar el valor por \"Todos los escritorios\".","Sí, al crear el escritorio virtual, accediendo al menú de opciones de ese escritorio virtual con el menú derecho del ratón.","Sí, en la configuración de la barra de tareas, “Varias pantallas” donde dice “En la barra de tareas, mostrar las ventanas que están abiertas en\", cambiar el valor por \"Todos los escritorios\"."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2022 extra · nº 45","justificaciones":["","Es esta. Sí se puede cambiar, en **Configuración > Sistema > Multitarea > Escritorios virtuales**. En **«En la barra de tareas, mostrar las ventanas que están abiertas en»** se pasa de «Solo en el escritorio que estoy usando» a **«Todos los escritorios»**.","",""],"ojo":"El ajuste está en **Multitarea**, no en la configuración de la barra de tareas. Una opción falsa lo coloca en «Varias pantallas», que es el apartado de la barra de tareas que gestiona otra cosa. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-04-046","origen":"oficiales","test":"INAP 2022 extra","n":46,"enunciado":"¿Cuál de los siguientes NO es un sistema de archivos utilizado por el sistema operativo Windows?","opciones":["NTFS","FAT","FAT32","FPS"],"correcta":3,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2022 extra · nº 46","justificaciones":["","","","Es esta. **FPS** no es un sistema de archivos, sino la sigla de «fotogramas por segundo». **NTFS**, **FAT** y **FAT32** sí son sistemas de archivos que utiliza Windows."],"ojo":"Los sistemas de archivos de Windows son NTFS, FAT, FAT32, exFAT y ReFS."},{"id":"win-in-04-047","origen":"oficiales","test":"INAP 2022 extra","n":47,"enunciado":"¿Con que combinación de teclas de las siguientes opciones puedo en Windows 11 quiero abrir Inicio?","opciones":["Alt + I","CTRL + Barra espaciadora","CTRL + I","CTRL + ESC"],"correcta":3,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2022 extra · nº 47","justificaciones":["","","","Es esta. **Ctrl + Esc** abre el **menú Inicio**, igual que la tecla con el logotipo de Windows."],"ojo":"Las demás combinaciones de la lista no abren Inicio. Para confundir, juegan con teclas como la I y la barra espaciadora, que tienen otros usos. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-04-048","origen":"oficiales","test":"INAP 2022 extra","n":48,"enunciado":"¿Pulsando qué teclas se hace aparecer la lupa en Windows 11?","opciones":["Tecla Windows + F3","Tecla Windows + F11","Tecla Windows y +","Tecla Windows + E"],"correcta":2,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2022 extra · nº 48","justificaciones":["","","Es esta. **Windows y la tecla +** abre la **Lupa** y aumenta el zoom. Con **Windows y -** se reduce, y **Windows + Esc** cierra la Lupa.",""],"ojo":"**Windows + E** abre el Explorador y no tiene que ver con la lupa. Las teclas de función no son atajos de la Lupa. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-04-049","origen":"oficiales","test":"INAP 2022 extra","n":49,"enunciado":"Señale la respuesta correcta sobre el explorador de Windows:","opciones":["Siempre muestra todos los archivos de la carpeta actual","Siempre muestra las extensiones de los archivos","Muestra siempre todas las carpetas dentro de la carpeta actual","Muestra opciones de configuración para permitir ver extensiones, carpetas o ficheros ocultos"],"correcta":3,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2022 extra · nº 49","justificaciones":["","","","Es esta. El Explorador de archivos tiene **opciones de configuración** en la pestaña **Ver > Mostrar** para ver u ocultar las **extensiones de nombre de archivo** y los **elementos ocultos**. Por tanto, no muestra siempre todo."],"ojo":"En las preguntas de opción múltiple, desconfía de las respuestas con «siempre» o «solo»: suelen ser las falsas."},{"id":"win-in-04-051","origen":"oficiales","test":"INAP 2022 extra","n":51,"enunciado":"¿Cuál es el sistema de archivos predeterminado utilizado por Windows 11?","opciones":["FAT32","exFAT","NTFS","ReFS"],"correcta":2,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2022 extra · nº 51","justificaciones":["","","Es esta. **NTFS** es el sistema de archivos **predeterminado** de Windows. Admite permisos, cifrado, compresión y archivos de gran tamaño.",""],"ojo":"**FAT32** y **exFAT** se usan sobre todo en memorias USB y tarjetas por su compatibilidad con otros sistemas. **ReFS** existe, pero es para servidores y almacenamiento especializado. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-05-045","origen":"oficiales","test":"INAP 14 dic. 2024","n":45,"enunciado":"Queremos hacer un tutorial de Windows 11 y necesitamos grabar vídeos con ejemplos de su utilización. ¿Cuál de las siguientes herramientas incluidas en Windows 11 es la más adecuada?","opciones":["Escritorio remoto.","La herramienta Recortes.","Paint.","La Grabadora de acciones de usuario."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 14 dic. 2024 · nº 45","justificaciones":["","Es esta. La herramienta **Recortes** de Windows 11 puede **grabar vídeo de la pantalla**, además de capturar imágenes. Es la más adecuada para un tutorial. Se abre con **Windows + Mayús + S** y se elige el modo de vídeo.","",""],"ojo":"**Escritorio remoto** conecta con otro equipo, **Paint** dibuja y la **Grabadora de acciones del usuario** solo guarda una secuencia de capturas con anotaciones, sin vídeo. Oficial reescrita para Windows 11: la original se refería a algo que cambió en esa versión."},{"id":"win-in-05-046","origen":"oficiales","test":"INAP 14 dic. 2024","n":46,"enunciado":"¿Cuál de las siguientes es una herramienta de accesibilidad de Windows 11?","opciones":["Cámara.","Visor XPS.","Narrador.","Sway."],"correcta":2,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 14 dic. 2024 · nº 46","justificaciones":["","","Es esta. El **Narrador** es el **lector de pantalla** de Windows 11: lee en voz alta lo que aparece en pantalla. Está en **Configuración > Accesibilidad**, y se activa con **Windows + Ctrl + Intro**.",""],"ojo":"La **Cámara**, el **Visor XPS** y **Sway** (aplicación para crear presentaciones y boletines) no son de accesibilidad. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-05-047","origen":"oficiales","test":"INAP 14 dic. 2024","n":47,"enunciado":"En Windows 11 en español utilizamos el método abreviado: logotipo de Windows + tecla E. ¿Cuál de las siguientes será la acción que producimos al hacerlo?","opciones":["Abrir el Explorador de archivos.","Minimiza las ventanas abiertas en Windows.","Cambiar entre aplicaciones abiertas.","Maximiza la ventana abierta."],"correcta":0,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 14 dic. 2024 · nº 47","justificaciones":["Es esta. **Windows + E** abre el **Explorador de archivos**, en Windows 11 igual que en versiones anteriores.","","",""],"ojo":"Para minimizar todo se usa **Windows + D**, para cambiar entre aplicaciones **Alt + Tab**, y para maximizar una ventana **Windows + Flecha arriba**. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-05-049","origen":"oficiales","test":"INAP 14 dic. 2024","n":49,"enunciado":"Queremos ver los procesos que se están ejecutando, así como el consumo de CPU y de memoria de un dispositivo con Windows 11. ¿Cuál de las siguientes herramientas es la adecuada?","opciones":["Propiedades del disco local (C:).","Visor de eventos.","Administrador de tareas.","Explorador de Windows."],"correcta":2,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 14 dic. 2024 · nº 49","justificaciones":["","","Es esta. El **Administrador de tareas** muestra los **procesos en ejecución** y su consumo de **CPU, memoria, disco y red**. Se abre con **Ctrl + Mayús + Esc** o con clic derecho en Inicio.",""],"ojo":"El **Visor de eventos** es un registro de sucesos pasados, no del uso actual. Las propiedades del disco C: solo informan del espacio. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-05-050","origen":"oficiales","test":"INAP 14 dic. 2024","n":50,"enunciado":"Estamos trabajando en Windows 11 con dos pantallas y queremos que cada pantalla pueda mostrar ventanas diferentes. ¿Cuál de las siguientes opciones tendremos que seleccionar en la configuración de pantallas?","opciones":["Duplicar estas pantallas.","Mostrar únicamente en 1.","Extender estas pantallas.","Mostrar únicamente en 2."],"correcta":2,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 14 dic. 2024 · nº 50","justificaciones":["","","Es esta. **Extender estas pantallas** reparte el escritorio entre las dos pantallas, de modo que cada una enseña ventanas distintas y se pueden arrastrar elementos de una a otra. Se elige en **Configuración > Sistema > Pantalla > Varias pantallas**.",""],"ojo":"**Duplicar** muestra lo mismo en ambas, y **Mostrar únicamente en 1** o **en 2** apaga la otra pantalla. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-05-051","origen":"oficiales","test":"INAP 14 dic. 2024","n":51,"enunciado":"¿Cuál es la utilidad de indexar archivos en la Búsqueda en Windows?","opciones":["Realizar copias de seguridad de los archivos, mensajes de correo electrónico u otro contenido local, como precaución de borrado en la búsqueda.","Copiar los archivos, mensajes de correo electrónico u otro contenido local en OneDrive y sincronizarlos con la copia local.","Seleccionar los archivos, mensajes de correo electrónico u otro contenido local para marcarlo y que no se utilice en las búsquedas.","Obtener resultado más rápidamente al buscar archivos, mensajes de correo electrónico u otro contenido local."],"correcta":3,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 14 dic. 2024 · nº 51","justificaciones":["","","","Es esta. **Indexar** crea un **índice** de nombres y contenido de archivos y correos, para que la **búsqueda sea más rápida**. Se configura en **Configuración > Privacidad y seguridad > Buscar en Windows**."],"ojo":"El índice no hace copias de seguridad ni sincroniza con OneDrive. Si quieres que una carpeta no aparezca en las búsquedas, se excluye en las mismas opciones."},{"id":"win-in-05-066","origen":"oficiales","test":"INAP 14 dic. 2024","n":66,"enunciado":"Estamos trabajando con dos pantallas en Windows 11. ¿Cuál de las siguientes opciones es verdadera en cuanto a la configuración de las pantallas?","opciones":["Podemos configurar la escala (tamaño de texto, aplicaciones, etc.), la resolución y la orientación, pero ha de ser la misma para las dos pantallas.","La escala (tamaño de texto, aplicaciones, etc.), la resolución y la orientación de las pantallas son configurables de forma independiente para cada pantalla.","Las dos pantallas han de tener la misma escala (tamaño de texto, aplicaciones, etc.) y orientación, pero pueden tener diferente resolución.","La escala y resolución de las pantallas son configurables, pero la orientación no lo es."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 14 dic. 2024 · nº 66","justificaciones":["","Es esta. Con dos pantallas, la **escala**, la **resolución** y la **orientación** se configuran **de forma independiente** para cada una. Se selecciona la pantalla (1 o 2) en **Configuración > Sistema > Pantalla** y se ajustan sus valores.","",""],"ojo":"Cuando se mezclan, por ejemplo, una pantalla horizontal y otra vertical, Windows lo permite. Ninguna de las otras opciones impone que sean iguales. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-06-048","origen":"oficiales","test":"INAP 2024 extra","n":48,"enunciado":"¿Cuál de las siguientes afirmaciones es correcta con respecto al idioma en Windows 11?","opciones":["Es posible configurar varios idiomas. El idioma configurado será siempre el mismo para mostrar Windows, la función de voz y el teclado.","Podemos elegir el idioma de instalación de Windows, pero una vez hecha la instalación no se puede modificar el idioma.","Podemos tener varios idiomas disponibles en la configuración y cambiar entre ellos, pero el que elijamos para mostrar Windows, tendrá que ser el mismo de la configuración del teclado.","Es posible configurar varios idiomas, y pueden ser diferentes para mostrar Windows, para la función de voz y para el teclado."],"correcta":3,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2024 extra · nº 48","justificaciones":["","","","Es esta. En Windows 11 se pueden configurar **varios idiomas** y que sean **distintos** para mostrar Windows, para la función de voz y para el teclado. Está en **Configuración > Hora e idioma > Idioma y región**."],"ojo":"El idioma se puede cambiar después de instalar. Y el idioma de la interfaz no obliga a usar el mismo en el teclado. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-06-049","origen":"oficiales","test":"INAP 2024 extra","n":49,"enunciado":"Dos usuarios comparten el mismo ordenador con Windows 11. ¿Cuál de las siguientes opciones es correcta con respecto al uso compartido?","opciones":["Windows solo admite una cuenta por ordenador. Será necesario que ambos compartan una misma cuenta, y compartir las aplicaciones Windows, si bien pueden crear escritorios diferentes y personalizados.","Windows es un sistema operativo multiusuario, pero las aplicaciones Windows, como Correo o Contactos, estarán obligatoriamente compartidas por ambos.","Windows solo admite una cuenta por ordenador. Será necesario que ambos compartan una misma cuenta, si bien pueden personalizar las aplicaciones Windows, como Correo o Contactos.","Windows es un sistema operativo multiusuario y cada usuario puede personalizar las aplicaciones Windows, como Correo o Contactos."],"correcta":3,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2024 extra · nº 49","justificaciones":["","","","Es esta. Windows es un sistema operativo **multiusuario**: cada persona tiene su **propia cuenta** y puede **personalizar** sus aplicaciones, su escritorio y su configuración sin afectar a las demás. Las cuentas se crean en **Configuración > Cuentas > Familia y otros usuarios**."],"ojo":"Las opciones que dicen «solo admite una cuenta por ordenador» son falsas, y también la que obliga a compartir las aplicaciones. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-06-050","origen":"oficiales","test":"INAP 2024 extra","n":50,"enunciado":"¿Cuál de las siguientes afirmaciones es correcta con respecto a los requisitos de hardware de las tarjetas gráficas para Windows 11?","opciones":["Los requisitos de hardware solo hacen mención del procesador y la memoria, no de las tarjetas gráficas.","No es necesario contar con tarjeta gráfica, si bien se recomienda para mejorar la visualización en la pantalla.","Es necesario contar con una tarjeta gráfica compatible (DirectX o WDDM).","En necesaria una tarjeta gráfica, si bien, cualquier tarjeta gráfica es compatible con Windows."],"correcta":2,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2024 extra · nº 50","justificaciones":["","","Es esta. Windows 11 exige una **tarjeta gráfica compatible con DirectX 12 o posterior y con un controlador WDDM 2.0**. Está entre los requisitos de hardware oficiales, junto al procesador, la RAM, el almacenamiento, el TPM 2.0 y el arranque seguro.",""],"ojo":"No es una recomendación opcional, y tampoco sirve cualquier tarjeta: tiene que ser compatible. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-06-051","origen":"oficiales","test":"INAP 2024 extra","n":51,"enunciado":"El Editor de Registro de Windows 11 es una herramienta que permite a los usuarios acceder y modificar la base de datos del registro del sistema operativo. ¿Cuál es el contenido de esta base de datos?.","opciones":["Contiene información crucial sobre la configuración del sistema, el hardware y las aplicaciones instaladas.","Contine información únicamente sobre la instalación y configuración de Windows.","Contiene información sobre las características de configuración modificadas por el usuario.","Contiene información sobre todas las aplicaciones instaladas en Windows, pero no del propio sistema operativo."],"correcta":0,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2024 extra · nº 51","justificaciones":["Es esta. El **Registro de Windows** es una **base de datos** con la configuración del **sistema**, del **hardware** y de las **aplicaciones instaladas**, así como de los usuarios. Se abre con **regedit** en el Editor del Registro.","","",""],"ojo":"Modificarlo a ciegas puede dejar el sistema sin arrancar, por eso conviene hacer una copia antes. No contiene solo lo que cambia el usuario ni solo las aplicaciones. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-06-052","origen":"oficiales","test":"INAP 2024 extra","n":52,"enunciado":"Necesitamos crear una copia de seguridad del sistema operativo y de los archivos esenciales en una unidad USB. ¿Cuál de las siguientes herramientas de Windows 11 será la adecuada?","opciones":["Administrador de equipos.","Servicios.","Unidad de recuperación.","Administrador de tareas."],"correcta":2,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2024 extra · nº 52","justificaciones":["","","Es esta. La **Unidad de recuperación** crea un **USB de recuperación** con el que se puede reinstalar o reparar Windows. Se abre buscando «Crear una unidad de recuperación» en Inicio y permite incluir los archivos del sistema.",""],"ojo":"El **Administrador de tareas** muestra procesos, **Servicios** gestiona servicios en segundo plano, y el **Administrador de equipos** agrupa herramientas de administración. Ninguno crea una copia de seguridad del sistema. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-06-054","origen":"oficiales","test":"INAP 2024 extra","n":54,"enunciado":"¿Cuál de los siguientes accesos directos del Explorador de archivos abre la configuración de Propiedades del elemento seleccionado?","opciones":["Tecla del logotipo de Windows + D.","Tecla del logotipo de Windows + Control + Q.","Tecla del logotipo de Windows + I.","Tecla Alt + Entrar."],"correcta":3,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2024 extra · nº 54","justificaciones":["","","","Es esta. **Alt + Entrar** abre las **Propiedades** del elemento seleccionado (archivo, carpeta o unidad). Equivale a clic derecho > Propiedades."],"ojo":"Los demás atajos hacen otra cosa: **Windows + D** muestra el escritorio y **Windows + I** abre la Configuración."},{"id":"win-in-06-055","origen":"oficiales","test":"INAP 2024 extra","n":55,"enunciado":"¿Cuál de las siguientes afirmaciones es correcta con respecto a la ordenación de los archivos en el Explorador de archivos de Windows 11?","opciones":["Es posible ordenar los archivos por distintos campos, aunque estos campos no se muestren en el diseño seleccionado.","Es posible ordenar los archivos solo por los campos que se muestran en el diseño seleccionado. Por ejemplo, si usamos uno de los diseños de iconos, solo es posible ordenar por el campo Nombre.","Solo se pueden ordenar por nombre o fecha de creación. El Explorador de archivos no dispone de otros campos para ordenar los archivos.","Solo es posible ordenar los archivos por campos en algunos de los diseños de entre todos los disponibles, que son: Lista, Detalles, y Contenido."],"correcta":0,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2024 extra · nº 55","justificaciones":["Es esta. En el Explorador de archivos se puede **ordenar por distintos campos** (nombre, fecha, tipo, tamaño…), **aunque no se vean** en el diseño elegido. Se hace con el botón **Ordenar** de la barra de herramientas.","","",""],"ojo":"Los diseños de iconos no muestran columnas, pero se puede seguir ordenando con **Ordenar**. En vista Detalles, además, se ordena haciendo clic en la cabecera de la columna. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-06-056","origen":"oficiales","test":"INAP 2024 extra","n":56,"enunciado":"En el Explorador de Windows 11 hacemos clic derecho sobre un fichero y seleccionamos la opción “Enviar a”. ¿Cuál de las siguientes respuestas describe las opciones correctas que se nos presentan?","opciones":["Aparecerá la ventana Compartir, donde añadiremos los contactos o correos electrónicos a los que vayamos a enviar el fichero por correo electrónico.","Ofrece varios destinos para enviar el fichero, como son Carpeta comprimida, Destinatario de correo, Destinatario de fax, Documentos, y otros.","Convierte el archivo seleccionado en un nuevo archivo comprimido de tipo zip, que deja en otra carpeta.","Abrirá un nuevo correo de Outlook con el archivo adjunto para que se agregue el destinatario, asunto y otros contenidos."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2024 extra · nº 56","justificaciones":["","Es esta. Clic derecho > **Mostrar más opciones > Enviar a** despliega varios **destinos**: **Carpeta comprimida**, **Destinatario de correo**, **Documentos**, el escritorio (crear acceso directo) y las unidades disponibles.","",""],"ojo":"No abre una ventana de compartir ni un correo de Outlook por sí solo, ni convierte el archivo en zip sin dejarlo en otra carpeta, como dicen las opciones falsas. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-06-057","origen":"oficiales","test":"INAP 2024 extra","n":57,"enunciado":"¿Cuál de las siguientes opciones es correcta con respecto a la Búsqueda disponible en la barra de herramientas de Windows 11?","opciones":["La búsqueda siempre se realiza en bibliotecas y escritorio y no es posible ningún tipo de personalización.","Es posible personalizar las ubicaciones en donde se realizan las búsquedas, incluyendo las carpetas localizadas en OneDrive.","Es posible personalizar las ubicaciones en donde se realizan las búsquedas, pero no es posible incluir OneDrive como ubicación.","Las búsquedas realizadas desde el cuadro de la barra de herramientas se realizan únicamente sobre las carpetas Documentos y Descargas."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2024 extra · nº 57","justificaciones":["","Es esta. Se pueden **personalizar las ubicaciones** donde busca Windows, **incluidas carpetas de OneDrive**. Se hace en **Configuración > Privacidad y seguridad > Buscar en Windows**, con el modo de búsqueda **Mejorado** o añadiendo carpetas.","",""],"ojo":"La búsqueda no se limita a bibliotecas y escritorio ni a Documentos y Descargas. Lo cierto es que es configurable. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-06-058","origen":"oficiales","test":"INAP 2024 extra","n":58,"enunciado":"¿Cuál es la función del Historial de archivos en Windows 11?","opciones":["Funciona como un control de versiones de archivos, guardando las distintas versiones del mismo archivo cuando se realizan cambios en él.","Es un fichero del sistema que recoge la fecha y hora de las modificaciones realizadas en los archivos almacenados dentro del equipo.","Es un fichero utilizado por Portapapeles de Windows 11 para almacenar el texto copiado de forma temporal.","Es una herramienta que te permite hacer copias de seguridad de los archivos y datos que están en el ordenador en una unidad externa o en una ubicación de red."],"correcta":3,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2024 extra · nº 58","justificaciones":["","","","Es esta. El **Historial de archivos** hace **copias de seguridad automáticas** de tus archivos (bibliotecas, escritorio, favoritos y contactos) en una **unidad externa** o en una **ubicación de red**, y permite restaurar versiones anteriores. Se activa en **Configuración > Sistema > Almacenamiento > Configuración avanzada de almacenamiento > Opciones de copia de seguridad**, o desde el Panel de control."],"ojo":"No es un control de versiones como el de Git ni el del Portapapeles. Es una herramienta de copia de seguridad. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"win-in-06-070","origen":"oficiales","test":"INAP 2024 extra","n":70,"enunciado":"¿Cuál de las siguientes afirmaciones es verdadera respecto al menú Inicio de Windows 11?","opciones":["Muestra las aplicaciones predefinidas por Windows en mosaicos dinámicos que no se pueden reorganizar.","Se divide en «Anclado» y «Recomendado», y el usuario decide qué aplicaciones, carpetas o archivos ancla.","Muestra únicamente las últimas aplicaciones instaladas, en mosaicos configurables.","Solo admite aplicaciones de Microsoft; el resto queda en «Todas las aplicaciones»."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 2024 extra · nº 70","justificaciones":["","Es esta. El menú **Inicio** de Windows 11 se divide en dos zonas: **Anclado**, donde el usuario decide qué aplicaciones, carpetas o archivos pone, y **Recomendado**, que muestra elementos y aplicaciones usados o instalados hace poco.","",""],"ojo":"Los **mosaicos dinámicos** (live tiles) de Windows 10 desaparecieron. El Inicio acepta aplicaciones de cualquier fabricante y se pueden reorganizar los iconos. Oficial reescrita para Windows 11: la original se refería a algo que cambió en esa versión."},{"id":"win-in-07-045","origen":"oficiales","test":"INAP 23 mayo 2026","n":45,"enunciado":"¿Cuál de las siguientes opciones permite acceder a las notificaciones de Windows 11?","opciones":["Las notificaciones están en la sección Accesibilidad de la Configuración, a la que se accede desde el menú de Inicio de Windows.","Las notificaciones están en el Centro de actividades, al que se acceden haciendo clic en el icono del Área de calendario y notificación en la esquina inferior derecha de la barra de tareas.","Las notificaciones están disponibles en el accesorio Noticias, al que se accede desde el menú de Inicio de Windows.","Las notificaciones están en el Menú de Windows, al que se accede en el icono de la barra de tareas o mediante la tecla Windows."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 23 mayo 2026 · nº 45","justificaciones":["","Es esta. Las notificaciones están en el **Centro de notificaciones**, que se abre haciendo clic en el área de **fecha y hora** de la esquina inferior derecha de la barra de tareas, o con **Windows + N**.","",""],"ojo":"En Windows 10 se llamaba **Centro de actividades**, un nombre que aún usan algunas preguntas antiguas. Accesibilidad es otro apartado de la Configuración."},{"id":"win-in-07-047","origen":"oficiales","test":"INAP 23 mayo 2026","n":47,"enunciado":"Señale cuál de las siguientes afirmaciones referidas a la búsqueda de Windows 11 es correcta:","opciones":["Windows Search busca en la web y los archivos, pero no busca en la configuración ni en aplicaciones y también puede incluir contenido de OneDrive, SharePoint, Outlook y Bing si se autoriza por el usuario.","Windows Search busca en la web, las aplicaciones, la configuración y los archivos, pero no incluye OneDrive, SharePoint o Outlook.","Windows Search busca en la web las aplicaciones, la configuración y los archivos y también puede incluir contenido de OneDrive, SharePoint, Outlook, Bing y otros servicios y aplicaciones si se autoriza por el usuario.","Windows Search solo busca en la web y los archivos almacenados en el dispositivo, incluyendo los de OneDrive solo si están sincronizados y almacenados en local, pero no realiza ninguna búsqueda en localizaciones externas al dispositivo."],"correcta":2,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 23 mayo 2026 · nº 47","justificaciones":["","","Es esta. **Windows Search** busca en la **web, aplicaciones, configuración y archivos**, y además puede incluir contenido de **OneDrive, SharePoint, Outlook y Bing**, siempre que lo autorice el usuario.",""],"ojo":"Las otras opciones recortan el alcance de la búsqueda, quitando la configuración, las aplicaciones o los servicios en la nube. Si ves una de ellas, es una trampa."},{"id":"win-in-07-048","origen":"oficiales","test":"INAP 23 mayo 2026","n":48,"enunciado":"¿Cuál de los siguientes grupos de diseños de vista del Explorador de archivos de Windows 11 tiene todos los elementos correctos?","opciones":["Iconos muy grandes – Contenido – Iconos muy pequeños.","Lista – Detalles – Iconos medianos.","Iconos muy pequeños – Extendido – Mosaico.","Mosaico – Iconos medianos – Extendido."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 23 mayo 2026 · nº 48","justificaciones":["","Es esta. Los diseños reales del Explorador de archivos son **iconos** (muy grandes, grandes, medianos y pequeños), **lista**, **detalles**, **mosaicos** y **contenido**. Por eso solo la opción **Lista, Detalles e Iconos medianos** es correcta del todo.","",""],"ojo":"**Extendido** no existe como diseño, y aparece en dos opciones para descartarlas."},{"id":"win-in-07-049","origen":"oficiales","test":"INAP 23 mayo 2026","n":49,"enunciado":"Hacemos un clic derecho de ratón sobre “Este equipo” en el Panel de navegación del Explorador de archivos de Windows 11 y seleccionamos la opción Propiedades. ¿Cuál de las siguientes opciones es la que se abre con esta acción?","opciones":["La ventana Propiedades del disco local C:","La Configuración de Windows en el apartado de Sistema.","La ventana de Administración de equipos.","El asistente para agregar una ubicación de red."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 23 mayo 2026 · nº 49","justificaciones":["","Es esta. Clic derecho sobre **Este equipo** > **Propiedades** abre **Configuración > Sistema > Información**, donde se ven las especificaciones del dispositivo y de Windows.","",""],"ojo":"Las propiedades del disco local C: se abren con clic derecho sobre la propia unidad. La Administración de equipos se abre con clic derecho > Administrar."},{"id":"win-in-07-050","origen":"oficiales","test":"INAP 23 mayo 2026","n":50,"enunciado":"¿Cuál es la funcionalidad del Accesorio de Windows 11 \"Asistencia rápida\"?","opciones":["Abrir una incidencia en el servicio de Soporte Técnico de Microsoft.","Acceder al sitio web que aloja la base de conocimientos (knowledge base) de Windows, con las preguntas y respuestas más habituales sobre el sistema operativo.","Permitir el acceso remoto y toma de control de nuestro dispositivo a otra persona, así como solicitar a otra persona que comparta su pantalla con nosotros.","Acceder a la configuración de la cuenta de Windows registrada en el sistema operativo, en la página de contraseñas guardadas."],"correcta":2,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 23 mayo 2026 · nº 50","justificaciones":["","","Es esta. **Asistencia rápida** permite que otra persona **tome el control remoto** de tu equipo para ayudarte, o que **tú veas** la pantalla de otra persona. Se abre buscando «Asistencia rápida» en Inicio e introduciendo un código de seis dígitos.",""],"ojo":"No abre incidencias de soporte ni lleva a la base de conocimiento de Microsoft. Es lo mismo que haría un técnico en remoto."},{"id":"win-in-07-067","origen":"oficiales","test":"INAP 23 mayo 2026","n":67,"enunciado":"¿Es posible anclar un sitio web al menú Inicio utilizando Microsoft Edge de Windows 11?","opciones":["No es posible, ya que en el menú Inicio sólo se pueden anclar aplicaciones de productividad.","No es posible, ya que los sitios web solo pueden guardarse como marcadores o favoritos en el navegador.","Sí es posible, haciendo clic en Configuración y más, luego Favoritos, y por último Anclar a Inicio.","Sí es posible, haciendo clic en Configuración y más, luego Más herramientas, y por último Anclar a Inicio."],"correcta":3,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · 23 mayo 2026 · nº 67","justificaciones":["","","","Es esta. Sí. En **Microsoft Edge**, **Configuración y más (···) > Más herramientas > Anclar a Inicio** coloca el sitio web como un icono del menú Inicio. Al hacer clic, se abre directamente esa página."],"ojo":"La ruta **Favoritos > Anclar a Inicio** es la trampa: la opción vive en **Más herramientas**, no en Favoritos."},{"id":"win-in-08-044","origen":"oficiales","test":"INAP julio 2026 extra","n":44,"enunciado":"¿Cuál es una de las características que diferencia principalmente el menú Inicio de Windows 11 respecto a versiones anteriores?","opciones":["Está centrado por defecto en la barra de tareas.","Incluye únicamente aplicaciones web.","No permite anclar aplicaciones.","No se puede personalizar."],"correcta":0,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · julio 2026 extra · nº 44","justificaciones":["Es esta. El cambio más visible del **menú Inicio de Windows 11** es que aparece **centrado** en la barra de tareas, junto a los iconos. Se puede devolver a la izquierda en **Configuración > Personalización > Barra de tareas > Comportamientos de la barra de tareas**.","","",""],"ojo":"El Inicio sí permite anclar aplicaciones y se puede personalizar. Tampoco se limita a aplicaciones web."},{"id":"win-in-08-046","origen":"oficiales","test":"INAP julio 2026 extra","n":46,"enunciado":"En Windows 11, ¿cuál es una de las funciones que tiene el Visor de eventos?","opciones":["Ejecutar programas.","Gestionar archivos y carpetas.","Registrar errores del sistema.","Cambiar configuración del calendario."],"correcta":2,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · julio 2026 extra · nº 46","justificaciones":["","","Es esta. El **Visor de eventos** es el **registro del sistema**: guarda errores, advertencias e información de Windows, de la seguridad y de las aplicaciones. Es la primera herramienta para investigar un fallo. Se abre buscando «Visor de eventos» o con eventvwr.",""],"ojo":"No ejecuta programas ni gestiona archivos ni cambia el calendario."},{"id":"win-in-08-047","origen":"oficiales","test":"INAP julio 2026 extra","n":47,"enunciado":"En Windows 11, ¿qué método abreviado de teclado permite hacer una captura de pantalla completa y guardarla por defecto subcarpeta Capturas de pantalla de la carpeta Imágenes?","opciones":["Impr Pant","Tecla Windows + Impr Pant","Tecla Windows + Mayús + S","No hay ninguna combinación que guarde directamente las capturas en archivo."],"correcta":1,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · julio 2026 extra · nº 47","justificaciones":["","Es esta. **Windows + Impr Pant** hace una captura de **pantalla completa** y la guarda como archivo en **Imágenes > Capturas de pantalla**.","",""],"ojo":"**Impr Pant** sola solo copia la captura al portapapeles, y **Windows + Mayús + S** abre la herramienta Recortes para elegir una zona."},{"id":"win-in-08-048","origen":"oficiales","test":"INAP julio 2026 extra","n":48,"enunciado":"En Windows 11, ¿qué ocurrirá al arrastrar un archivo de una unidad a otra manteniendo pulsada las teclas Ctrl + MAYÚS?","opciones":["Se copiará el archivo en la nueva unidad.","Se moverá el archivo a la nueva unidad.","Se creará un acceso directo del archivo en la nueva unidad.","No se realizará ninguna acción."],"correcta":2,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · julio 2026 extra · nº 48","justificaciones":["","","Es esta. Al arrastrar un archivo con **Ctrl + Mayús** pulsadas se crea un **acceso directo** en el destino, sin copiar ni mover el archivo.",""],"ojo":"Arrastrar entre unidades distintas **copia** por defecto, y entre carpetas de la misma unidad **mueve**. Con **Ctrl** se fuerza copiar y con **Mayús** se fuerza mover."},{"id":"win-in-08-050","origen":"oficiales","test":"INAP julio 2026 extra","n":50,"enunciado":"En el Explorador de archivos de Windows 11, al eliminar un archivo desde una unidad local, ¿en qué situación no será posible recuperarlo desde la Papelera de reciclaje?","opciones":["Cuando el archivo se elimina desde una unidad configurada para no pasar por la papelera o usando la combinación “Mayús+ Supr”.","Cuando el archivo se elimina desde una carpeta con permisos restringidos para el usuario actual.","Cuando el archivo pertenece a un tipo específico que no admite almacenamiento temporal.","Cuando el archivo ha sido modificado recientemente antes de su eliminación."],"correcta":0,"bloque":"windows-general","precepto":"Pregunta oficial del INAP · julio 2026 extra · nº 50","justificaciones":["Es esta. Un archivo **no se puede recuperar de la Papelera** cuando se elimina con **Mayús + Supr** (borrado definitivo) o cuando la unidad está configurada para no usar papelera. También ocurre con las unidades extraíbles y de red.","","",""],"ojo":"No influye si el archivo se modificó hace poco ni qué tipo de archivo sea. Los permisos tampoco impiden la papelera."}]});
